mapper.select:
SELECT

FROM asset ass

LEFT JOIN idc idc ON ass.idc_id = idc.id
LEFT JOIN cabinet cab ON ass.cabinet_id = cab.id
LEFT JOIN asset_ping assp ON ass.host = assp.host
LEFT JOIN model mo ON ass.model_id = mo.id
LEFT JOIN sys_dict sdt ON sdt.code = mo.vendor AND sdt.type = 'vendor'
LEFT JOIN sys_dict sdtt ON sdtt.code = mo.type AND sdtt.type = 'assetType'
LEFT JOIN sys_user su ON idc.principal = su.user_id



        ass.id = #{params.id}



        AND ass.model_id = #{params.modelId}



        AND ass.model_id IN

            #{modelId}




        AND ass.idc_id = #{params.idcId}



        AND ass.idc_id IN

            #{idcId}



        AND ass.state IN

            #{state}



        AND ass.cabinet_id = #{params.cabinetId}



        AND ass.state = #{params.state}



        AND ass.host like CONCAT('%', #{params.host}, '%')



        AND ass.sn like CONCAT('%', #{params.sn}, '%')



        AND ass.purchase_date like CONCAT('%', #{params.purchaseDate}, '%')



        AND assp.status = #{params.pingStatus}



        AND cab.name LIKE CONCAT('%', #{params.cabinetName}, '%')



        AND assp.status IN

            #{status}




        AND ass.id IN

            #{id}




        AND ass.id IN

            #{id}





    ORDER BY ass.id
